from pathlib import Path
import re
L=Path('/app/dataset/genealogy_trees.txt').read_text().splitlines()
for row in range(40,82):
 s=L[row-1]
 segs=[(m.start(),m.end()-1,m.group()[:70]) for m in re.finditer(r'\S(?:.{0,6}?\S)?', '')]
 runs=[]
 for m in re.finditer(r'\S.*?(?= {10,}|$)',s):
  if m.end()>=2500 and m.start()<=4000:
   runs.append((m.start(),m.end()-1,m.group().strip()[:100]))
 print(f'{row:03d}',runs)
PY",workdir:"/app",max_output_tokens:15000});text(r.output);

